using RestSharp;\nusing Serilog;\nusing System;\n\nnamespace AutomationFramework.API.BusinessLogic {\n    public class PetApiHelper {\n        private readonly RestClient _client;\n\n        public PetApiHelper() {\n            _client = new RestClient("https://petstore.swagger.io/v2");\n        }\n\n        public RestResponse SendPostRequest(string endpoint, string payload) {\n            var request = new RestRequest(endpoint, Method.Post);\n            request.AddHeader("Content-Type", "application/json");\n            request.AddJsonBody(payload);\n            Log.Information("Sending POST request to {Endpoint} with payload: {Payload}", endpoint, payload);\n            var response = _client.Execute(request);\n            Log.Information("Received response: {StatusCode} - {Content}", response.StatusCode, response.Content);\n            return response;\n        }\n\n        public RestResponse SendGetRequest(string endpoint) {\n            var request = new RestRequest(endpoint, Method.Get);\n            Log.Information("Sending GET request to {Endpoint}", endpoint);\n            var response = _client.Execute(request);\n            Log.Information("Received response: {StatusCode} - {Content}", response.StatusCode, response.Content);\n            return response;\n        }\n\n        public RestResponse SendPutRequest(string endpoint, string payload) {\n            var request = new RestRequest(endpoint, Method.Put);\n            request.AddHeader("Content-Type", "application/json");\n            request.AddJsonBody(payload);\n            Log.Information("Sending PUT request to {Endpoint} with payload: {Payload}", endpoint, payload);\n            var response = _client.Execute(request);\n            Log.Information("Received response: {StatusCode} - {Content}", response.StatusCode, response.Content);\n            return response;\n        }\n\n        public RestResponse SendDeleteRequest(string endpoint) {\n            var request = new RestRequest(endpoint, Method.Delete);\n            Log.Information("Sending DELETE request to {Endpoint}", endpoint);\n            var response = _client.Execute(request);\n            Log.Information("Received response: {StatusCode} - {Content}", response.StatusCode, response.Content);\n            return response;\n        }\n    }\n}